package com.saysharp.shared.session

import com.saysharp.shared.practice.PracticeStage
import com.saysharp.shared.practice.RecordingSlot

private fun ordinary(
    day: Int, title: String, objective: String, instruction: String, technique: String,
    scenario: String, question: String, check: String, hint: String,
    weak: String, strong: String, why: String, correction: String, transfer: String, realWorld: String,
    limitSeconds: Int = 60, retrySeconds: Int = limitSeconds, transferSeconds: Int = limitSeconds,
    preparationSeconds: Int = 15,
) = SessionDefinition(
    day = day, title = title, objective = objective, instruction = instruction, technique = technique,
    scenario = scenario, selfCheck = check, listeningHint = hint,
    weakExample = weak, correctiveExample = strong, exampleExplanation = why, correction = correction,
    realWorldApplication = realWorld, preparationSeconds = preparationSeconds,
    suggestedSeconds = 30..limitSeconds,
    prompts = mapOf(
        RecordingSlot.First to SpeakingPrompt("${lessonId(day)}-first", question, limitSeconds * 1_000L),
        RecordingSlot.Retry to SpeakingPrompt("${lessonId(day)}-retry", question, retrySeconds * 1_000L),
        RecordingSlot.Application to SpeakingPrompt("${lessonId(day)}-transfer", transfer, transferSeconds * 1_000L),
    ),
    stages = listOf(PracticeStage.Welcome, PracticeStage.FirstAttempt, PracticeStage.FirstCheck,
        PracticeStage.Lesson, PracticeStage.Retry, PracticeStage.Compare, PracticeStage.Apply, PracticeStage.Complete),
)

private fun checkpoint(day: Int, title: String, objective: String, fresh: String, check: String, hint: String, reflection: String) = SessionDefinition(
    day = day, title = title, objective = objective,
    instruction = "Answer the familiar question before listening to your earlier recording. Then answer a new question in your own words.",
    technique = "Choose your own structure without a model answer.",
    selfCheck = check, listeningHint = hint, correctiveExample = "",
    checkpoint = CheckpointContent(lessonId(1), reflection),
    realWorldApplication = if (day == 7) "Notice whether someone can follow your next explanation without asking you to start over."
        else "Choose one observable speaking habit to keep using in your next three conversations.",
    prompts = mapOf(
        RecordingSlot.Baseline to SpeakingPrompt("${lessonId(day)}-reference", DayOneSession.scenario + "\n\n" + DayOneSession.prompts.getValue(RecordingSlot.First).text, 60_000),
        RecordingSlot.CheckpointRepeat to SpeakingPrompt("${lessonId(day)}-familiar", DayOneSession.scenario + "\n\n" + DayOneSession.prompts.getValue(RecordingSlot.First).text, 60_000),
        RecordingSlot.CheckpointFresh to SpeakingPrompt("${lessonId(day)}-fresh", fresh, 60_000),
    ),
    stages = listOf(PracticeStage.CheckpointRepeat, PracticeStage.CheckpointFresh, PracticeStage.CheckpointCompare, PracticeStage.Summary, PracticeStage.Complete),
)

